  ("l", ["ab: liquid is compressed with no change in entropy by an ideal pump", "bc: constant pressure transfer of heat in the boiler", "cd: constant entropy expansion with shaft work output in an ideal turbine", "da: constant pressure transfer of heat in the sink"], 61),
  ("f", "ht-01-fig20", "Steam plant loop: steam generator to turbine, condenser, condensate pump, feed pump, and back to the steam generator."),
