 dict(title="Condenser cooling water flow", tag=WS, eo="1.23", page=67, problem="Steam flows through a condenser at 2.0 x 10⁶ kg/hr, entering at h = 2574 kJ/kg and leaving at h = 125.8 kJ/kg. Cooling water goes from h = 75.6 to h = 104.9 kJ/kg. Find the cooling water flow.", steps=["Heat lost by steam equals heat gained by cooling water", "ṁcw = 2.0 x 10⁶ (2574 - 125.8)/(104.9 - 75.6)"], answer="1.67 x 10⁸ kg/hr"),
